/* PIANO-UI-007 — permanent deterministic MotionEngine tests.
 *
 * Every case runs in Node against the pure handmotion.js module: no DOM,
 * no Three.js, no timers. Keyboard truth comes from the ONE canonical
 * geometry (app.js noteCenterFraction); where material must come from
 * the Core, the fixtures generated by the accepted canonical Python
 * pipeline (tests/weblogic/fixtures/) are used — fingering is NEVER
 * reimplemented here.
 *
 * Run: node tests/weblogic/handmotion.test.mjs
 */
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { join } from "node:path";

import { noteCenterFraction, PIANO_NOTE_MIN, PIANO_NOTE_MAX } from "../../src/piano_core/web/static/app.js";
import {
  APPROACH_MAX_LEAD_SECONDS,
  contactIntegrity,
  contactPointForKey,
  createMotionView,
  evaluate,
  KEYBOARD_WIDTH_M,
  MOTION_SCHEMA_VERSION,
  MOTION_WARNINGS,
  PHASES,
  PRESS_SECONDS,
  solveHandPose,
  validateOccupancy,
} from "../../src/piano_core/web/static/handmotion.js";

const HERE = fileURLToPath(new URL(".", import.meta.url));

/* ---------------- canonical geometry + plan helpers ---------------- */

const GEOMETRY = {
  centerFractions: (() => {
    const map = new Map();
    for (let midi = PIANO_NOTE_MIN; midi <= PIANO_NOTE_MAX; midi += 1) {
      map.set(midi, noteCenterFraction(midi));
    }
    return map;
  })(),
};

let planCounter = 0;
function makePlan(targets) {
  planCounter += 1;
  return {
    schema_version: 1,
    engine_version: "balanced-engine-v1",
    plan_id: `fingering-sha256:${String(planCounter).padStart(64, "0")}`,
    song_id: "test-song",
    source_version: `score-sha256:${"a".repeat(64)}`,
    version: 1,
    generation: 1,
    strategy: "balanced_v1",
    provenance: "DETERMINISTIC_INFERENCE",
    targets,
    warnings: [],
    excluded_note_count: 0,
    config: { strategy: "balanced_v1", max_hand_span_semitones: 12, alternative_count: 1 },
  };
}

let targetCounter = 0;
function target({ midi, onset, duration, hand = "RIGHT", finger = 3, channel = 1 }) {
  targetCounter += 1;
  return {
    score_index: targetCounter - 1,
    target_id: `score:${targetCounter - 1}`,
    midi,
    channel,
    onset_seconds: onset,
    duration_seconds: duration,
    hand,
    finger,
    alternatives: [],
  };
}

function viewOf(targets, { songId = "test-song" } = {}) {
  return createMotionView({
    songId,
    sourceVersion: `score-sha256:${"a".repeat(64)}`,
    plan: makePlan(targets),
    geometry: GEOMETRY,
  });
}

function fixture(name) {
  return JSON.parse(readFileSync(join(HERE, "fixtures", name), "utf8"));
}

function fixtureView(name) {
  const payload = fixture(name);
  return createMotionView({
    songId: payload.score.song_id,
    sourceVersion: payload.score.source_version,
    plan: payload.fingering,
    geometry: GEOMETRY,
  });
}

/* ---------------- tiny runner ---------------- */

let failures = 0;
let passes = 0;
function test(name, fn) {
  try {
    fn();
    passes += 1;
    console.log(`ok - ${name}`);
  } catch (error) {
    failures += 1;
    console.error(`FAIL - ${name}`);
    console.error(error);
  }
}

/* ---------------- 1-2: single notes, both hands ---------------- */

test("single RH note: APPROACH -> PRESS -> HOLD -> RELEASE -> RECOVER", () => {
  const view = viewOf([target({ midi: 60, onset: 1, duration: 0.5 })]);
  const before = evaluate(view, 0.98, 1);
  assert.equal(before.hands.RIGHT.fingers[3].phase, "APPROACH");
  assert.equal(before.hands.RIGHT.fingers[3].press, 0);
  assert.equal(before.hands.LEFT, null);

  const at = evaluate(view, 1.001, 1);
  const fm = at.hands.RIGHT.fingers[3];
  assert.equal(fm.phase, "PRESS");
  assert.ok(fm.press > 0 && fm.press < 1);
  assert.equal(fm.midi, 60);

  const held = evaluate(view, 1.2, 1);
  assert.equal(held.hands.RIGHT.fingers[3].phase, "HOLD");
  assert.equal(held.hands.RIGHT.fingers[3].press, 1);

  const released = evaluate(view, 1.45, 1); // release window [1.38, 1.5)
  assert.equal(released.hands.RIGHT.fingers[3].phase, "RELEASE");
  assert.ok(released.hands.RIGHT.fingers[3].press < 1);

  const recovered = evaluate(view, 1.6, 1); // recover window [1.5, 1.7)
  assert.equal(recovered.hands.RIGHT.fingers[3].phase, "RECOVER");
  assert.equal(recovered.hands.RIGHT.fingers[3].press, 0);

  const resting = evaluate(view, 1.9, 1); // past recovery: hover rest
  assert.equal(resting.hands.RIGHT.fingers[3].phase, "PREPARE");
});

test("single LH note mirrors hand identity but never the key", () => {
  const view = viewOf([target({ midi: 48, onset: 0, duration: 1, hand: "LEFT", finger: 5 })]);
  const state = evaluate(view, 0.2, 1);
  assert.equal(state.hands.LEFT.hand, "LEFT");
  assert.equal(state.hands.RIGHT, null);
  const pose = solveHandPose(state.hands.LEFT);
  assert.equal(pose.hand, "LEFT");
  assert.equal(contactIntegrity(state.hands.LEFT, pose), true);
});

/* ---------------- repeated note ---------------- */

test("repeated note: deterministic re-press on the same key", () => {
  const view = viewOf([
    target({ midi: 64, onset: 0, duration: 0.2 }),
    target({ midi: 64, onset: 0.3, duration: 0.2 }),
    target({ midi: 64, onset: 0.6, duration: 0.2 }),
  ]);
  const pressA = evaluate(view, 0.02, 1).hands.RIGHT.fingers[3];
  const pressB = evaluate(view, 0.32, 1).hands.RIGHT.fingers[3];
  assert.equal(pressA.midi, 64);
  assert.equal(pressB.midi, 64);
  assert.ok(pressA.press > 0);
  assert.ok(pressB.press > 0);
  // identical phase at equal relative offsets: deterministic behavior
  const a = evaluate(view, 0.1, 1).hands.RIGHT.fingers[3].press;
  const b = evaluate(view, 0.4, 1).hands.RIGHT.fingers[3].press;
  assert.ok(Math.abs(a - b) < 1e-12);
});

/* ---------------- 3: scales (canonical fixture material) ---------------- */

test("RH/LH scale fixture: both hands present, no warnings, all phases valid", () => {
  const view = fixtureView("thumb_under_scale.json");
  const state = evaluate(view, 1.0, 1);
  assert.ok(state.hands.RIGHT);
  assert.ok(state.hands.LEFT);
  assert.deepEqual(state.warnings, []);
  for (const hand of ["LEFT", "RIGHT"]) {
    const pose = solveHandPose(state.hands[hand]);
    assert.equal(contactIntegrity(state.hands[hand], pose), true);
  }
});

/* ---------------- 4: thumb-under fixture ---------------- */

test("thumb-under fixture: thumb plays after crossing without clamp", () => {
  const view = fixtureView("thumb_under_scale.json");
  const rh = view.hands.RIGHT.attacks;
  const thumbAttacks = rh.filter((a) => a.finger === 1);
  assert.ok(thumbAttacks.length >= 1, "fixture contains thumb attacks");
  for (const attack of thumbAttacks) {
    const state = evaluate(view, attack.onset + PRESS_SECONDS / 2, 1);
    const pose = solveHandPose(state.hands.RIGHT);
    assert.equal(pose.fingers[1].clamped, false);
    assert.equal(contactIntegrity(state.hands.RIGHT, pose), true);
  }
});

/* ---------------- 5: chords arrive together ---------------- */

for (const count of [3, 4, 5]) {
  test(`${count}-note chord: all fingers press together at the onset`, () => {
    const midis = [60, 64, 67, 72, 76].slice(0, count);
    const fingers = [1, 2, 3, 4, 5].slice(0, count);
    const view = viewOf(
      midis.map((midi, i) => target({ midi, onset: 1, duration: 0.5, finger: fingers[i] }))
    );
    const mid = evaluate(view, 1.02, 1).hands.RIGHT;
    for (let i = 0; i < count; i += 1) {
      const fm = mid.fingers[fingers[i]];
      assert.equal(fm.phase, "PRESS", `finger ${fingers[i]}`);
      assert.ok(fm.press > 0, `finger ${fingers[i]} press`);
      assert.equal(fm.midi, midis[i]);
    }
    const pose = solveHandPose(mid);
    assert.equal(contactIntegrity(mid, pose), true);
  });
}

/* ---------------- 6: held chord + moving finger (fixture) ---------------- */

test("held chord + moving finger fixture: held contact immutable while top moves", () => {
  const view = fixtureView("chords_held_moving.json");
  const held = view.hands.LEFT.attacks[0];
  for (const p of [1.6, 2.0, 2.4, 2.9]) {
    const state = evaluate(view, p, 1);
    if (!state.hands.LEFT) continue;
    const fm = state.hands.LEFT.fingers[held.finger];
    if (fm.contact && fm.press > 0) {
      assert.equal(fm.contact.x, held.contact.x);
      assert.equal(fm.contact.z, held.contact.z);
      const pose = solveHandPose(state.hands.LEFT);
      assert.equal(contactIntegrity(state.hands.LEFT, pose), true);
    }
  }
});

/* ---------------- 7: bass + melody (fixture) ---------------- */

test("bass + melody fixture: hands stay separated and warning-free", () => {
  const view = fixtureView("bass_melody.json");
  for (const p of [0.5, 4.2, 8.2, 11.05, 11.9]) {
    const state = evaluate(view, p, 1);
    assert.deepEqual(state.warnings, []);
    for (const hand of ["LEFT", "RIGHT"]) {
      if (!state.hands[hand]) continue;
      const pose = solveHandPose(state.hands[hand]);
      assert.equal(contactIntegrity(state.hands[hand], pose), true);
    }
    if (state.hands.LEFT && state.hands.RIGHT) {
      const delta = state.hands.RIGHT.root.x - state.hands.LEFT.root.x;
      assert.ok(delta > 0, "hands ordered LEFT below RIGHT");
    }
  }
});

/* ---------------- 8: converging/diverging hands ---------------- */

test("converging then diverging hands keep their own keys", () => {
  const view = viewOf([
    target({ midi: 55, onset: 0, duration: 2, hand: "LEFT", finger: 1 }),
    target({ midi: 60, onset: 0, duration: 2, hand: "RIGHT", finger: 1 }),
    target({ midi: 48, onset: 3, duration: 1, hand: "LEFT", finger: 1 }),
    target({ midi: 72, onset: 3, duration: 1, hand: "RIGHT", finger: 1 }),
  ]);
  const converging = evaluate(view, 1, 1);
  assert.ok(
    converging.hands.RIGHT.root.x > converging.hands.LEFT.root.x
  );
  assert.equal(converging.hands.LEFT.fingers[1].midi, 55);
  assert.equal(converging.hands.RIGHT.fingers[1].midi, 60);
  const diverging = evaluate(view, 3.5, 1);
  assert.ok(
    diverging.hands.RIGHT.root.x - diverging.hands.LEFT.root.x >= 0.09 - 1e-9
  );
  assert.equal(diverging.hands.LEFT.fingers[1].midi, 48);
});

/* ---------------- 9: large jump ---------------- */

test("large jump: bounded approach lead and exact landing", () => {
  const view = viewOf([
    target({ midi: 24, onset: 0, duration: 0.5, hand: "RIGHT", finger: 1 }),
    target({ midi: 108, onset: 2, duration: 0.5, hand: "RIGHT", finger: 1 }),
  ]);
  const mid = evaluate(view, 1.5, 1).hands.RIGHT.fingers[1];
  assert.equal(mid.phase, "APPROACH");
  // lead is bounded even across the full 88-key span
  assert.ok(mid.approachProgress >= 0 && mid.approachProgress <= 1);
  const landing = evaluate(view, 2.02, 1).hands.RIGHT;
  const pose = solveHandPose(landing);
  assert.equal(contactIntegrity(landing, pose), true);
});

/* ---------------- 10: fast repetition ---------------- */

test("fast repetition: newest attack owns the finger deterministically", () => {
  const targets = [];
  for (let i = 0; i < 8; i += 1) {
    targets.push(target({ midi: 72, onset: i * 0.12, duration: 0.1 }));
  }
  const view = viewOf(targets);
  for (const p of [0.05, 0.17, 0.29, 0.41]) {
    const fm = evaluate(view, p, 1).hands.RIGHT.fingers[3];
    assert.ok(
      fm.phase === "PRESS" || fm.phase === "HOLD" ||
      fm.phase === "APPROACH" || fm.phase === "RELEASE",
      `phase ${fm.phase} at p=${p}`
    );
    assert.equal(fm.midi, 72, "newest attack owns the finger");
  }
  const a = JSON.stringify(evaluate(view, 0.5, 1));
  const b = JSON.stringify(evaluate(view, 0.5, 1));
  assert.equal(a, b);
});

/* ---------------- 11: long sustain ---------------- */

test("long sustain: HOLD for the whole canonical duration, exact contact", () => {
  const view = viewOf([target({ midi: 45, onset: 0.5, duration: 8, hand: "LEFT", finger: 2 })]);
  for (const p of [1, 3, 5, 7.5, 8.3]) {
    const state = evaluate(view, p, 1);
    const fm = state.hands.LEFT.fingers[2];
    assert.equal(fm.phase, "HOLD", `p=${p}`);
    assert.equal(fm.press, 1);
    const pose = solveHandPose(state.hands.LEFT);
    assert.equal(contactIntegrity(state.hands.LEFT, pose), true);
  }
});

/* ---------------- 12: zero-duration never held ---------------- */

test("zero-duration note: PRESS then RELEASE, never HOLD, no occupancy", () => {
  const view = viewOf([target({ midi: 67, onset: 1, duration: 0 })]);
  assert.equal(view.hands.RIGHT.attacks.length, 1);
  const pressing = evaluate(view, 1.02, 1).hands.RIGHT.fingers[3];
  assert.equal(pressing.phase, "PRESS");
  const releasing = evaluate(view, 1.05 + 1e-6, 1).hands.RIGHT.fingers[3];
  assert.notEqual(releasing.phase, "HOLD");
  const after = evaluate(view, 1 + PRESS_SECONDS + 0.12 + 1e-6, 1)
    .hands.RIGHT.fingers[3];
  assert.equal(after.press, 0);
  // and it creates no occupancy: a different note on the same finger
  // overlapping it is NOT a violation
  const view2 = viewOf([
    target({ midi: 67, onset: 1, duration: 0 }),
    target({ midi: 70, onset: 1, duration: 2, finger: 3 }),
  ]);
  assert.deepEqual(view2.warnings, []);
  assert.ok(view2.hands.RIGHT);
});

/* ---------------- 13: pause freezes pose; seek reconstructs ---------------- */

test("pause freezes pose; seek reconstructs immediately", () => {
  const view = viewOf([target({ midi: 60, onset: 1, duration: 2 })]);
  const t = 1.5;
  const a = JSON.stringify(evaluate(view, t, 1));
  const b = JSON.stringify(evaluate(view, t, 1));
  assert.equal(a, b, "same position -> identical state (pause frozen)");
  const seeked = evaluate(view, 2.9, 1);
  assert.equal(seeked.hands.RIGHT.fingers[3].phase, "RELEASE");
  // seek back reconstructs exactly the earlier state
  assert.equal(JSON.stringify(evaluate(view, t, 1)), a);
});

/* ---------------- 14: tempo re-anchor ---------------- */

test("tempo re-anchor: rate changes lead times, never phase truth", () => {
  const view = viewOf([
    target({ midi: 60, onset: 0, duration: 0.4, finger: 1 }),
    target({ midi: 65, onset: 1, duration: 0.4, finger: 1 }),
  ]);
  const slow = evaluate(view, 0.9, 1).hands.RIGHT.fingers[1];
  const fast = evaluate(view, 0.9, 4).hands.RIGHT.fingers[1];
  // faster tempo -> more song-seconds of lead -> approach starts earlier
  // and is further along at the same canonical position
  assert.equal(fast.phase, "APPROACH");
  assert.ok(fast.approachProgress > slow.approachProgress);
  // phase windows themselves are rate-independent
  const atPress = evaluate(view, 1.01, 4).hands.RIGHT.fingers[1];
  assert.equal(atPress.phase, "PRESS");
});

/* ---------------- 15: same-source deterministic reconstruction -------- */

test("same-source deterministic reconstruction: identical views and states", () => {
  const build = () => fixtureView("chords_held_moving.json");
  const v1 = build();
  const v2 = build();
  assert.equal(JSON.stringify(v1), JSON.stringify(v2));
  assert.equal(
    JSON.stringify(evaluate(v1, 2.345, 1.25)),
    JSON.stringify(evaluate(v2, 2.345, 1.25))
  );
  assert.equal(v1.identity.planId, v2.identity.planId);
});

/* ---------------- 16: occupancy violation is rejected, not repaired ---- */

test("occupancy violation: hand omitted fail-closed, other hand intact", () => {
  const view = viewOf([
    target({ midi: 60, onset: 0, duration: 2, hand: "LEFT", finger: 3 }),
    target({ midi: 64, onset: 1, duration: 2, hand: "LEFT", finger: 3 }),
    target({ midi: 72, onset: 0, duration: 1, hand: "RIGHT", finger: 3 }),
  ]);
  assert.ok(view.hands.LEFT.omitted);
  assert.equal(view.hands.LEFT.omittedReason, MOTION_WARNINGS.OCCUPANCY_VIOLATION);
  assert.deepEqual(view.hands.LEFT.attacks, []);
  assert.ok(view.hands.RIGHT);
  assert.ok(view.warnings.includes("plan_occupancy_violation:LEFT"));
  const state = evaluate(view, 0.5, 1);
  assert.equal(state.hands.LEFT, null);
  assert.ok(state.hands.RIGHT);
  // boundary: touching half-open intervals are NOT a violation
  const touching = viewOf([
    target({ midi: 60, onset: 0, duration: 1, hand: "LEFT", finger: 3 }),
    target({ midi: 64, onset: 1, duration: 1, hand: "LEFT", finger: 3 }),
  ]);
  assert.equal(touching.hands.LEFT.omitted, false);
});

/* ---------------- 17: same-MIDI overlap allowed ---------------- */

test("same-MIDI overlap is an alias, not a violation", () => {
  const view = viewOf([
    target({ midi: 60, onset: 0, duration: 2, finger: 2 }),
    target({ midi: 60, onset: 0.5, duration: 3, finger: 2 }),
  ]);
  assert.equal(view.hands.RIGHT.omitted, false);
  assert.deepEqual(view.warnings, []);
});

/* ---------------- 18: dense collision warns, truth untouched ----------- */

test("dense chromatic cluster: collisions may warn but contacts never move", () => {
  const view = viewOf([
    target({ midi: 60, onset: 0, duration: 2, finger: 1 }),
    target({ midi: 61, onset: 0, duration: 2, finger: 2 }),
    target({ midi: 62, onset: 0, duration: 2, finger: 3 }),
    target({ midi: 63, onset: 0, duration: 2, finger: 4 }),
    target({ midi: 64, onset: 0, duration: 2, finger: 5 }),
  ]);
  const state = evaluate(view, 1, 1);
  const pose = solveHandPose(state.hands.RIGHT);
  // contact immutability under dense collision (hard invariant)
  assert.equal(contactIntegrity(state.hands.RIGHT, pose), true);
  for (let finger = 1; finger <= 5; finger += 1) {
    const fm = state.hands.RIGHT.fingers[finger];
    const tip = pose.fingers[finger].tip;
    assert.ok(Math.abs(tip.x - fm.contact.x) < 1e-6, `finger ${finger} x`);
    assert.ok(Math.abs(tip.z - fm.contact.z) < 1e-6, `finger ${finger} z`);
  }
  // the deterministic warning vocabulary only
  for (const warning of pose.warnings) {
    assert.ok(
      [MOTION_WARNINGS.COLLISION_UNRESOLVED, MOTION_WARNINGS.POSE_CLAMPED].includes(warning)
    );
  }
});

/* ---------------- 19: contact immutability across the whole song ------- */

test("contact immutability: pressed tips sit exactly on canonical contacts", () => {
  const view = fixtureView("bass_melody.json");
  for (let p = 0; p <= 12.5; p += 0.17) {
    const state = evaluate(view, p, 1);
    for (const hand of ["LEFT", "RIGHT"]) {
      if (!state.hands[hand]) continue;
      const pose = solveHandPose(state.hands[hand]);
      assert.equal(
        contactIntegrity(state.hands[hand], pose),
        true,
        `hand ${hand} at p=${p.toFixed(2)}`
      );
    }
  }
});

/* ---------------- 20: NaN/Infinity rejection --------------------------- */

test("NaN/Infinity inputs are rejected without poisoning state", () => {
  const view = viewOf([target({ midi: 60, onset: 1, duration: 1 })]);
  assert.throws(() => evaluate(view, NaN, 1), TypeError);
  assert.throws(() => evaluate(view, Infinity, 1), TypeError);
  assert.throws(() => evaluate(view, 1, NaN), TypeError);
  assert.throws(() => evaluate(view, 1, Infinity), TypeError);
  assert.throws(() => evaluate(view, -1, 1), TypeError);
  assert.throws(() => evaluate(view, 1, 0), TypeError);
  // non-finite plan targets are DROPPED deterministically (non-throwing)
  const hostile = viewOf([
    { midi: 60, channel: 1, onset_seconds: NaN, duration_seconds: 1, hand: "RIGHT", finger: 2, score_index: 90, target_id: "score:90", alternatives: [] },
    { midi: 62, channel: 1, onset_seconds: Infinity, duration_seconds: 1, hand: "RIGHT", finger: 3, score_index: 91, target_id: "score:91", alternatives: [] },
    { midi: 64, channel: 1, onset_seconds: 1, duration_seconds: 1, hand: "RIGHT", finger: 3, score_index: 92, target_id: "score:92", alternatives: [] },
  ]);
  assert.deepEqual(hostile.warnings, [`${MOTION_WARNINGS.INVALID_TARGET_DROPPED}:2`]);
  assert.equal(hostile.hands.RIGHT.attacks.length, 1);
  assert.ok(evaluate(hostile, 1.01, 1).hands.RIGHT);
});

/* ---------------- structural invariants ---------------- */

test("view construction is non-throwing for hostile payloads", () => {
  const garbage = createMotionView({
    songId: "s",
    sourceVersion: "score-sha256:" + "a".repeat(64),
    plan: { targets: [null, {}, { midi: "x" }, 42] },
    geometry: GEOMETRY,
  });
  assert.equal(garbage.schemaVersion, MOTION_SCHEMA_VERSION);
  assert.deepEqual(garbage.warnings, [`${MOTION_WARNINGS.INVALID_TARGET_DROPPED}:4`]);
  assert.equal(garbage.hands.RIGHT.attacks.length, 0);
  const state = evaluate(garbage, 1, 1);
  assert.equal(state.hands.LEFT, null);
  assert.equal(state.hands.RIGHT, null);
});

test("phase model is exactly the locked six phases", () => {
  assert.deepEqual([...PHASES], [
    "PREPARE", "APPROACH", "PRESS", "HOLD", "RELEASE", "RECOVER",
  ]);
});

test("validateOccupancy: half-open interval boundary semantics", () => {
  const attacks = (a, b) => [
    { duration: 1, onset: a, midi: 60, finger: 2 },
    { duration: 1, onset: b, midi: 64, finger: 2 },
  ];
  assert.equal(validateOccupancy(attacks(0, 0.999)), true, "overlap violates");
  assert.equal(validateOccupancy(attacks(0, 1)), false, "touching is fine");
  assert.equal(validateOccupancy(attacks(0, 0.5)), true, "nested violates");
});

test("contacts derive exactly from the canonical geometry fractions", () => {
  const contact = contactPointForKey(60, GEOMETRY.centerFractions);
  const fraction = GEOMETRY.centerFractions.get(60);
  assert.ok(Math.abs(contact.x - (fraction - 0.5) * KEYBOARD_WIDTH_M) < 1e-12);
  assert.equal(contact.band, "white");
  const black = contactPointForKey(61, GEOMETRY.centerFractions);
  assert.equal(black.band, "black");
  assert.ok(black.y > contact.y);
  assert.ok(black.z > contact.z, "black contact nearer the player");
});

/* ---------------- report ---------------- */

console.log(`\n${passes} passed, ${failures} failed`);
if (failures > 0) process.exit(1);
